{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "HI-240, a close analogue containing the same thiourea linker and a heteroaromatic bromopyridine, achieved brain concentrations comparable to plasma in mice, directly demonstrating that this thiourea/heteroaromatic chemotype crosses the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Ropinirole, which shares the dipropylamino pharmacophore, showed brain-to-blood ratios of 1.2–1.6 in rats and similar brain/plasma exposure in monkeys without P-gp involvement, supporting CNS access for the dipropylamino-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "HI-236, another thiourea-containing analogue, showed brain concentrations comparable to plasma in mice, reinforcing that the thiourea motif does not preclude meaningful brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "NGP 555, a heteroaromatic CNS agent with an imidazole-containing core, had a brain:plasma ratio of 0.93 in Tg2576 mice, supporting meaningful CNS access for the query's imidazole/heteroaromatic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Lidocaine, a tertiary-amine small molecule, showed high brain uptake within 5 minutes in rats and CSF/plasma ratios near 0.9 in humans, supporting that tertiary-amine-containing molecules can achieve robust CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer experimental records show that structurally related molecules with tertiary amines, thiourea linkers, and heteroaromatic cores readily cross the BBB, with brain/plasma ratios near 1 and robust CSF/brain uptake. The query shares these key features, so meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement exists for the exact query molecule; the prediction relies on close analogues.",
    "The exact efflux-transporter profile of the query was not directly measured, although a closely related dipropylamino analogue showed no P-gp involvement."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

